// Helper function to check if two line segments intersect
auto segmentsIntersect = [](const Point2d& p1, const Point2d& p2, const Point2d& p3, const Point2d& p4) -> bool {
    auto orientation = [](const Point2d& a, const Point2d& b, const Point2d& c) -> int {
        double val = (b.y - a.y) * (c.x - b.x) - (b.x - a.x) * (c.y - b.y);
        if (std::abs(val) < 1e-9) return 0; // collinear
        return (val > 0) ? 1 : 2; // 1 = clockwise, 2 = counter-clockwise
    };

    auto onSegment = [](const Point2d& a, const Point2d& b, const Point2d& c) -> bool {
        return c.x >= std::min(a.x, b.x) && c.x <= std::max(a.x, b.x) &&
               c.y >= std::min(a.y, b.y) && c.y <= std::max(a.y, b.y);
    };

    int o1 = orientation(p1, p2, p3);
    int o2 = orientation(p1, p2, p4);
    int o3 = orientation(p3, p4, p1);
    int o4 = orientation(p3, p4, p2);

    if (o1 != o2 && o3 != o4) return true;
    if (o1 == 0 && onSegment(p1, p2, p3)) return true;
    if (o2 == 0 && onSegment(p1, p2, p4)) return true;
    if (o3 == 0 && onSegment(p3, p4, p1)) return true;
    if (o4 == 0 && onSegment(p3, p4, p2)) return true;

    return false;
};

